#nullable enable
public sealed record Customer(string Name, string? Email, Address? Address);

static string Contact(Customer customer)
{
    // Warning CS8602: Address may be null here.
    // return customer.Address.City;

    if (customer.Address is { } address)          // null check + binding
        return address.City;

    return customer.Email?.ToLowerInvariant()      // ?. short-circuits to null
        ?? "no contact";                           // ?? supplies a fallback
}

public sealed class CreateCustomerRequest
{
    public required string Name { get; init; }   // must be set by the object initializer
    public string? Email { get; init; }
}

// System.Text.Json does not enforce non-nullable annotations by default:
var request = JsonSerializer.Deserialize<Contact>("{\"Name\": null}");
// request.Name is null even though Name is declared as string.
